    """Retourne la durée précise d'un fichier WAV en lisant son en-tête (en millisecondes)."""
    try:
        with wave.open(audio_path, 'rb') as w:
            frames = w.getnframes()
            rate = w.getframerate()
            if rate > 0:
                return frames / float(rate)
    except Exception as e:
